pub type Student = { id: Int; name: Str; }

impl PartialEq for Student {
  fn eq(self: &Student, other: &Student) -> Bool {
    return self.id == other.id;
  }
}
impl Eq for Student {}

impl Hash for Student {
  fn hash(self: &Student, state: &mut Hasher) {
    self.id.hash(state);
  }
}

fn main() -> Int {
  let mut map = HashMap[Int, Student]();
  map.insert(1, Student{ id: 1, name: "Kilo" });
  let s = map.get(&1);
  return match s { Some(student) => student.name.len(), None => 0, };
}
